from __future__ import annotations

import base64
import logging
import os
import urllib.parse
from typing import (
    Any,
    Dict,
)

from langchain_core.messages import (
    AIMessage,
    BaseMessage,
    ChatMessage,
    FunctionMessage,
    HumanMessage,
    SystemMessage,
    ToolMessage,
)

logger = logging.getLogger(__name__)


def _is_url(s: str) -> bool:
    try:
        result = urllib.parse.urlparse(s)
        return all([result.scheme, result.netloc])
    except Exception as e:
        logger.debug(f"Unable to parse URL: {e}")
        return False


def _url_to_b64_string(image_source: str) -> str:
    try:
        if _is_url(image_source):
            return image_source
        elif image_source.startswith("data:image"):
            return image_source
        elif os.path.exists(image_source):
            with open(image_source, "rb") as f:
                image_data = f.read()
                import filetype  # type: ignore

                kind = filetype.guess(image_data)
                image_type = kind.extension if kind else "unknown"
                encoded = base64.b64encode(image_data).decode("utf-8")
                return f"data:image/{image_type};base64,{encoded}"
        else:
            raise ValueError(
                "The provided string is not a valid URL, base64, or file path."
            )
    except Exception as e:
        raise ValueError(f"Unable to process the provided image source: {e}")


def _normalize_content(content: Any) -> Any:
    """Normalize message content to handle LangChain 1.0 content blocks.

    In LangChain 1.0, `message.content` can be:

    - A string (traditional)
    - A list of content blocks (new in v1.0)
    - `None`

    This function converts list content to string or `None` as needed.

    For multimodal content (images), returns the list as-is.
    """
    if content is None or isinstance(content, str):
        return content

    if not isinstance(content, list):
        return str(content)

    # Process list of content blocks
    text_parts = []

    for block in content:
        if isinstance(block, str):
            text_parts.append(block)
        elif isinstance(block, dict):
            block_type = block.get("type")

            # Preserve multimodal content (images and videos) as-is for VLM models
            if block_type in ("image_url", "image", "video_url", "video"):
                return content

            # Extract text from text blocks
            if block_type == "text" and "text" in block:
                text_parts.append(block["text"])
            # Ignore other block types (tool_call, etc.) - they're handled elsewhere

    # Join text blocks, return None if empty
    result = "".join(text_parts)
    return result if result else None


def convert_message_to_dict(message: BaseMessage) -> dict:
    """Convert a LangChain message to a dictionary.

    Args:
        message: The LangChain message.

    Returns:
        The dictionary.
    """
    message_dict: Dict[str, Any]
    if isinstance(message, ChatMessage):
        message_dict = {
            "role": message.role,
            "content": _normalize_content(message.content),
        }
    elif isinstance(message, HumanMessage):
        message_dict = {
            "role": "user",
            "content": _normalize_content(message.content),
        }
    elif isinstance(message, AIMessage):
        message_dict = {
            "role": "assistant",
            "content": _normalize_content(message.content),
        }
        # Forward reasoning fields only when they originated from separate API
        # response fields, not from <think> tags.
        api_fields = message.additional_kwargs.get("_reasoning_api_fields", [])
        if "reasoning_content" in api_fields:
            message_dict["reasoning_content"] = message.additional_kwargs[
                "reasoning_content"
            ]
        if "reasoning" in api_fields:
            message_dict["reasoning"] = message.additional_kwargs["reasoning"]
        if "function_call" in message.additional_kwargs:
            message_dict["function_call"] = message.additional_kwargs["function_call"]
            # If function call only, content is None not empty string
            if message_dict["content"] == "":
                message_dict["content"] = None
        if "tool_calls" in message.additional_kwargs:
            message_dict["tool_calls"] = message.additional_kwargs["tool_calls"]
            # If tool calls only, content is None not empty string
            if message_dict["content"] == "":
                message_dict["content"] = None
    elif isinstance(message, SystemMessage):
        message_dict = {
            "role": "system",
            "content": _normalize_content(message.content),
        }
    elif isinstance(message, FunctionMessage):
        message_dict = {
            "role": "function",
            "content": _normalize_content(message.content),
            "name": message.name,
        }
    elif isinstance(message, ToolMessage):
        message_dict = {
            "role": "tool",
            "content": _normalize_content(message.content),
            "tool_call_id": message.tool_call_id,
        }
    else:
        raise TypeError(f"Got unknown type {message}")
    if "name" in message.additional_kwargs:
        message_dict["name"] = message.additional_kwargs["name"]
    return message_dict

import base64

import pytest
from langchain_core.documents import Document

from langchain_nvidia_ai_endpoints import NVIDIARerank


@pytest.mark.parametrize(
    "img",
    [
        "tests/data/nvidia-picasso.jpg",
        "tests/data/nvidia-picasso.png",
        "tests/data/nvidia-picasso.webp",
        "tests/data/nvidia-picasso.gif",
        f"""data:image/jpg;base64,{
            base64.b64encode(
                open('tests/data/nvidia-picasso.jpg', 'rb').read()
            ).decode('utf-8')
        }""",
    ],
    ids=["jpg", "png", "webp", "gif", "data"],
)
@pytest.mark.parametrize(
    "func", ["compress", "acompress"], ids=["compress", "acompress"]
)
@pytest.mark.asyncio
async def test_vlm_reranker_image_type(
    rerank_vlm_model: str, mode: dict, func: str, img: str
) -> None:
    ranker = NVIDIARerank(model=rerank_vlm_model, **mode)
    documents = [
        Document(
            page_content="A colorful cat with a frog and Times Square.",
            metadata={"image": img},
        ),
        Document(page_content="The weather today is sunny."),
    ]
    query = "Show me a picture of a cat or a frog"
    if func == "compress":
        results = ranker.compress_documents(documents=documents, query=query)
    else:
        results = await ranker.acompress_documents(documents=documents, query=query)
    assert len(results) > 0
    for doc in results:
        assert "relevance_score" in doc.metadata
        assert isinstance(doc.metadata["relevance_score"], float)


